`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Documented surfaces."})," ",e.jsx(t.a,{href:"https://experienceleague.adobe.com/en/docs/substance-3d-dev/painter-python/tutorials/remote-control",children:"Substance Painter remote control"})," drives a running authoring application; it does not establish a headless bake/export acceptance contract. The ",e.jsx(t.a,{href:"https://openimageio.readthedocs.io/en/latest/oiiotool.html",children:"OpenImageIO oiiotool manual"}),", displayed as 3.3.0 when checked, documents ",e.jsx(t.code,{children:"--info"}),", ",e.jsx(t.code,{children:"--colorconvert"}),", ",e.jsx(t.code,{children:"--diff"})," and ",e.jsx(t.code,{children:"--absdiff"}),". Most commands normally operate on the first subimage and discard others; ",e.jsx(t.code,{children:"-a"})," and subimage selection modifiers control broader processing. Named color transforms depend on the selected configuration. This is a rolling manual, not a pinned binary."]}),`
