`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Documented surfaces."})," The rolling ",e.jsx(t.a,{href:"https://ffmpeg.org/ffmpeg-filters.html",children:"FFmpeg filter manual"})," documents ",e.jsx(t.code,{children:"ebur128"})," M/S/I/LRA measurements; true-peak mode oversamples and requires libswresample. ",e.jsx(t.code,{children:"astats"})," supplies channel/overall statistics; ",e.jsx(t.code,{children:"Peak_count"})," counts extrema occasions, not clipped samples. ",e.jsx(t.code,{children:"silencedetect"})," announces silence after a duration threshold; end/duration metadata appears after silence. ",e.jsx(t.code,{children:"mono=1"})," separates channels. For mono input intended for stereo playback, the manual calls for ",e.jsx(t.code,{children:"dualmono"})," compensation; its ",e.jsx(t.code,{children:"panlaw"})," setting also affects the measurement. No installed FFmpeg configuration was checked."]}),`
