`,e.jsxs(t.p,{children:[e.jsx(t.strong,{children:"Documented boundaries."})," ",e.jsx(t.a,{href:"https://docs.godotengine.org/en/4.4/classes/class_projectsettings.html#class-projectsettings-method-load-resource-pack",children:"ProjectSettings.load_resource_pack"})," mounts PCK/ZIP content into ",e.jsx(t.code,{children:"res://"})," and returns a boolean. Same-path entries replace existing entries by default; ",e.jsx(t.code,{children:"replace_files=false"})," disables that replacement. The 4.4 reference cautions that ",e.jsx(t.code,{children:"DirAccess"})," does not show changes to ",e.jsx(t.code,{children:"res://"})," made by this operation. A directory listing is therefore not the acceptance oracle for newly mounted content."]}),`
